<?php require __DIR__.'/../bootstrap/app.php';login_required();$db=Database::get();$uid=(int)user()['id'];
$s=$db->prepare("SELECT q.id,q.quantity,q.status,q.created_at,p.name FROM quotations q LEFT JOIN products p ON p.id=q.product_id WHERE q.customer_id=? ORDER BY q.id DESC");$s->execute([$uid]);$rows=$s->fetchAll();
$ids=array_map(fn($r)=>(int)$r['id'],$rows);$resp=[];$docs=[];
if($ids){$in=implode(',',$ids);foreach($db->query("SELECT quotation_id,price,message,created_at FROM quotation_responses WHERE quotation_id IN($in) ORDER BY id DESC")->fetchAll() as $x)$resp[$x['quotation_id']][]=$x;foreach($db->query("SELECT id,quotation_id,original_name FROM uploaded_documents WHERE quotation_id IN($in)")->fetchAll() as $x)$docs[$x['quotation_id']][]=$x;}
$title='My quotations';require __DIR__.'/../app/Views/header.php';?><section class="section"><div class="container"><h1>My quotations</h1><?php if(!$rows):?><p>No requests yet. <a href="<?=e(url('products.php'))?>">Browse products</a>.</p><?php endif;?>
<?php foreach($rows as $r):?><div class="cardx mb-3"><b><?=e($r['name'])?></b> × <?=(int)$r['quantity']?> · <small><?=e($r['created_at'])?></small> · <span class="badge bg-secondary"><?=e($r['status'])?></span>
<?php foreach($resp[$r['id']]??[] as $x):?><div class="alert alert-success mt-2 mb-1"><small><?=e($x['created_at'])?></small><br><?=$x['price']!==null?'<b>Quoted price: '.e($x['price']).' ETB</b><br>':''?><?=nl2br(e($x['message']))?></div><?php endforeach;?>
<?php foreach($docs[$r['id']]??[] as $d):?><div><a href="<?=e(url('download.php?id='.(int)$d['id']))?>">📎 <?=e($d['original_name'])?></a></div><?php endforeach;?>
<form method="post" action="<?=e(url('documents.php'))?>" enctype="multipart/form-data" class="d-flex gap-2 mt-2"><?=csrf_field()?><input type="hidden" name="quotation_id" value="<?=(int)$r['id']?>"><input class="form-control form-control-sm" type="file" name="doc" accept=".pdf,.jpg,.jpeg,.png" required><button class="btn btn-sm btn-outline-dark">Attach document</button></form></div><?php endforeach;?></div></section><?php require __DIR__.'/../app/Views/footer.php';?>